import React, { useCallback, useEffect, useRef, useState } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import { ArrowRight, ArrowUpRight, Copy, Check, Github } from 'lucide-react';
import { FlipPhoto, MagneticButton } from './ui';
import { GITHUB_URL } from '../data/work';

const EASE = [0.16, 1, 0.3, 1];
const EMAIL = 'info@ethanzhou.ca';

/*
 * A copy button, not a mailto.
 *
 * The original CTA was a bare `mailto:`, which silently does nothing for
 * anyone without a default mail client registered. That is most people
 * reading webmail in a browser tab, so the button just looked broken.
 *
 * Now the label is the address, pressing it copies, and it says so.
 * execCommand is kept as a fallback because navigator.clipboard is undefined
 * outside a secure context.
 */
function EmailButton() {
  const [copied, setCopied] = useState(false);
  const timer = useRef(null);

  useEffect(() => () => clearTimeout(timer.current), []);

  const flash = useCallback(() => {
    setCopied(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setCopied(false), 2000);
  }, []);

  const copy = useCallback(() => {
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(EMAIL).then(flash, legacyCopy);
      return;
    }
    legacyCopy();

    function legacyCopy() {
      const el = document.createElement('textarea');
      el.value = EMAIL;
      el.setAttribute('readonly', '');
      el.style.cssText = 'position:absolute;left:-9999px';
      document.body.appendChild(el);
      el.select();
      try {
        document.execCommand('copy');
        flash();
      } finally {
        document.body.removeChild(el);
      }
    }
  }, [flash]);

  return (
    <button
      type="button"
      onClick={copy}
      data-hover
      aria-label={`Copy email address ${EMAIL}`}
      /* Fixed min-width: the label swap shrinks the button from ~205px to
         ~119px otherwise, which shoves the github button sideways. */
      className="inline-flex min-w-[13rem] items-center justify-center gap-2 whitespace-nowrap rounded-full bg-slate-900 px-6 py-3 text-sm font-medium text-white shadow-card transition-all duration-300 hover:shadow-card-hover active:translate-y-px dark:bg-slate-50 dark:text-slate-900"
    >
      {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
      <span>{copied ? 'copied' : EMAIL}</span>
      {/* Announced to screen readers without shifting the visible label. */}
      <span aria-live="polite" className="sr-only">
        {copied ? 'Email address copied to clipboard' : ''}
      </span>
    </button>
  );
}

/*
 * Hero.
 *
 * Replaces the old centred stack (Caveat handwriting headline, "eng student
 * who makes things on the internet", three pill buttons in a row). That version
 * said nothing specific and looked like every other student portfolio.
 *
 * Layout is an asymmetric split at DESIGN_VARIANCE 7: copy left, portrait
 * right, collapsing to a single column under md.
 *
 * Hero stack discipline: 3 text elements (headline, subtext, CTAs). No eyebrow,
 * no trust strip, no scroll cue.
 */
export default function Home({ navigate }) {
  const reduce = useReducedMotion();
  const rise = (delay) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 24 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.7, delay, ease: EASE },
        };

  return (
    <>
      <section className="mx-auto flex min-h-[calc(100dvh-68px)] max-w-5xl flex-col justify-center px-6 pt-8 pb-16 md:pt-16">
        <div className="grid items-center gap-10 md:grid-cols-[1.35fr_0.65fr] md:gap-16">
          <div>
            {/* Plain text, not per-letter spans. ProximityText marked every
                letter aria-hidden and appended an sr-only copy of the whole
                line, so selecting the headline picked up both and pasting gave
                you "i build software,i build software,". */}
            <motion.h1
              {...rise(0.05)}
              className="text-[2.4rem] font-semibold leading-[1.08] tracking-tight text-slate-900 dark:text-slate-50 sm:text-[3.1rem] md:text-[3.5rem]"
            >
              hi, i&rsquo;m ethan.
            </motion.h1>

            <motion.p
              {...rise(0.15)}
              className="mt-6 max-w-[48ch] text-base leading-relaxed text-slate-600 dark:text-slate-400 sm:text-lg"
            >
              i build developer tools for mobile teams, and make short videos
              about money.
            </motion.p>

            <motion.div {...rise(0.25)} className="mt-9 flex flex-wrap items-center gap-3">
              <MagneticButton>
                <EmailButton />
              </MagneticButton>

              <MagneticButton>
                <a
                  href={GITHUB_URL}
                  target="_blank"
                  rel="noopener noreferrer"
                  data-hover
                  className="inline-flex items-center gap-2 whitespace-nowrap rounded-full border border-slate-300 px-6 py-3 text-sm font-medium text-slate-700 transition-all duration-300 hover:border-slate-400 hover:bg-white active:translate-y-px dark:border-slate-700 dark:text-slate-300 dark:hover:border-slate-600 dark:hover:bg-slate-900"
                >
                  <Github className="h-4 w-4" />
                  github
                </a>
              </MagneticButton>
            </motion.div>
          </div>

          <motion.div
            {...rise(0.2)}
            className="order-first flex justify-center md:order-none md:justify-end"
          >
            <FlipPhoto className="h-40 w-40 sm:h-52 sm:w-52 md:h-60 md:w-60" />
          </motion.div>
        </div>
      </section>

      <TwoTracks navigate={navigate} />
    </>
  );
}

